style.css:
@-moz-document domain("www.google.com") {
/* ============================================
     3. Замена надписи "Google" на "Burmagoogogagal"
     ============================================ */

  /* Скрываем оригинальный логотип на главной */
  img.lnXdpd,
  #hplogo,
  .k1zIA.rSk4se,
  img[alt="Google"] {
    visibility: hidden !important;
    position: relative !important;
  }

  /* Создаём новую надпись поверх логотипа */
  img.lnXdpd::after,
  #hplogo::after,
  .k1zIA.rSk4se::after,
  img[alt="Google"]::after {
    content: "Burmagoogogagal" !important;
    visibility: visible !important;
    display: block !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-size: 64px !important;
    font-family: 'Product Sans', Arial, sans-serif !important;
    font-weight: bold !important;
    background: linear-gradient(
      90deg,
      #4285F4 0%,
      #4285F4 16%,
      #EA4335 16%,
      #EA4335 33%,
      #FBBC05 33%,
      #FBBC05 50%,
      #4285F4 50%,
      #4285F4 58%,
      #34A853 58%,
      #34A853 75%,
      #EA4335 75%,
      #EA4335 100%
    ) !important;
    -webkit-background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    background-clip: text !important;
    white-space: nowrap !important;
    z-index: 9999 !important;
  }

  /*
     Поскольку img не поддерживает ::after,
     используем обёртку логотипа:
  */
  .k1zIA.rSk4se {
    position: relative !important;
    overflow: visible !important;
  }

  .k1zIA.rSk4se::after {
    content: "Burmagoogogagal" !important;
    visibility: visible !important;
    display: block !important;
    position: absolute !important;
    top: 50% !important;
    left: 50% !important;
    transform: translate(-50%, -50%) !important;
    font-size: 58px !important;
    font-family: 'Product Sans', Arial, sans-serif !important;
    font-weight: 500 !important;
    background: linear-gradient(
      90deg,
      #4285F4,
      #EA4335,
      #FBBC05,
      #4285F4,
      #34A853,
      #EA4335
    ) !important;
    -webkit-background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    background-clip: text !important;
    white-space: nowrap !important;
    z-index: 10000 !important;
  }

  /* ============================================
     2. При наведении на область логотипа —
        картинка с размытием 50%
     ============================================ */

  .k1zIA.rSk4se::before {
    content: "" !important;
    display: none !important;
    position: fixed !important;
    top: 0 !important;
    left: 0 !important;
    width: 100vw !important;
    height: 100vh !important;
    background-image: url("https://encrypted-tbn0.gstatic.com/images?q=tbn:ANd9GcTJP0EjGxv8fTrTE9FvNw0veyEqgLANXOTxcg&s") !important;
    background-size: cover !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    filter: blur(8px) !important;
    opacity: 0.5 !important;
    z-index: 9998 !important;
    pointer-events: none !important;
    transition: opacity 0.3s ease !important;
  }

  .k1zIA.rSk4se:hover::before {
    display: block !important;
    animation: fadeInBlur 0.5s ease forwards !important;
  }

  @keyframes fadeInBlur {
    from {
      opacity: 0;
    }
    to {
      opacity: 0.5;
    }
  }

  /* ============================================
     4. Картинка в области поиска при появлении
        подсказок (автодополнение)
     ============================================ */

  /* Контейнер подсказок */
  .aajZCb,
  .UUbT9,
  ul[role="listbox"],
  .erkvQe,
  .sbct {
    position: relative !important;
  }

  /* Картинка перед подсказками */
  .aajZCb::before,
  ul[role="listbox"]::before {
    content: "" !important;
    display: block !important;
    width: 100% !important;
    height: 120px !important;
    background-image: url("https://avatars.mds.yandex.net/i?id=3e65141bf9ada17b24b93b4554bd3604341bd2dd-6950099-images-thumbs&n=13") !important;
    background-size: contain !important;
    background-position: center !important;
    background-repeat: no-repeat !important;
    margin-bottom: 8px !important;
    border-radius: 8px !important;
    animation: searchImgAppear 0.6s ease !important;
    z-index: 9999 !important;
  }

  @keyframes searchImgAppear {
    0% {
      opacity: 0;
      transform: scale(0.5);
    }
    50% {
      opacity: 0.7;
      transform: scale(1.05);
    }
    100% {
      opacity: 1;
      transform: scale(1);
    }
  }

  /* ============================================
     Бонус: стилизация фона страницы
     ============================================ */
  body {
    background-color: #1a1a2e !important;
  }

  /* Чтобы надпись была видна на тёмном фоне */
  .k1zIA.rSk4se:hover::after {
    text-shadow: 0 0 20px rgba(255,255,255,0.3) !important;
    z-index: 10001 !important;
  }
}
